$current=$db->get('turmas',$t);$enrollmentBefore=$db->get('matriculas',(int)$initial['idmatricula']);$contractBefore=$db->get('contratos',$ct);
$cat->classRenewal($t,['versao'=>$current['versao'],'idturma_proxima'=>null],keyP());$current=$db->get('turmas',$t);$cat->classRenewal($t,['versao'=>$current['versao'],'idturma_proxima'=>$future],keyP());testP((int)$db->get('turmas',$t)['idturma_proxima']===$future,'turma ocupada aceita alteração isolada da rematrícula');testP($db->get('matriculas',(int)$initial['idmatricula'])===$enrollmentBefore&&$db->get('contratos',$ct)===$contractBefore,'destino alterado não muda matrícula nem contrato atuais');deniedP(fn()=>$cat->classRenewal($t,['versao'=>$current['versao'],'idturma_proxima'=>null],keyP()),'destino exige versão atual');
