wp_set_current_user($rfUser);deniedP(fn()=>$integration->detail('alunos',$student),'responsável não acessa API global de integração');deniedP(fn()=>$integration->createStudent($data,keyP()),'responsável não grava pela integração');echo "PASS: APIs de integração concluídas\n";
